<?php
declare(strict_types=1);use DecisionRules\RuleSetRepository;require __DIR__.'/_auth.php';$auth->requireAnyRole(['RULE_APPROVER','ADMIN','VIEWER']);$repo=new RuleSetRepository($pdo);$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$set=$id?$repo->find($id):null;if(!$set||$set['status']!=='PENDING_APPROVAL'){http_response_code(404);exit('Pending Rule Set not found.');}$diff=$repo->diff((int)$id);$title='Review Rule Set v'.$set['version'];$activePage='approvals';require __DIR__.'/partials/header.php';?>
<section class="rule-hero panel"><div><span class="badge off">PENDING APPROVAL</span><h2>Rule Set v<?=(int)$set['version']?></h2><p><?=e($set['name']?:'Unnamed')?> · <?=e($set['rule_count'])?> rules</p><p>Created by <?=e($set['created_by_username']?:'System')?> at <?=e($set['created_at'])?> · Submitted by <?=e($set['submitted_by_username'])?> at <?=e($set['submitted_at'])?></p><p><?=nl2br(e($set['submission_comment']?:$set['comment']?:'No comment.'))?></p></div></section>
<?php foreach(['added'=>'Added Rules','removed'=>'Removed Rules','modified'=>'Modified Rules','unchanged'=>'Unchanged Rules'] as $key=>$label):?><section class="panel"><h2><?=e($label)?> (<?=count($diff[$key])?>)</h2><?php foreach($diff[$key] as $code=>$change):?><details><summary><strong><?=e($code)?></strong></summary><?php if($key==='modified'):?><div class="table-wrap"><table><thead><tr><th>Field</th><th>Before</th><th>After</th></tr></thead><tbody><?php foreach(['stage_name','avg_actual_pd','priority','active','description','conditions'] as $field):?><?php if($change['before'][$field]!=$change['after'][$field]):?><tr><td><?=e($field)?></td><td><pre><?=e(is_array($change['before'][$field])?json_encode($change['before'][$field],JSON_PRETTY_PRINT):$change['before'][$field])?></pre></td><td><pre><?=e(is_array($change['after'][$field])?json_encode($change['after'][$field],JSON_PRETTY_PRINT):$change['after'][$field])?></pre></td></tr><?php endif;?><?php endforeach;?></tbody></table></div><?php endif;?></details><?php endforeach;?></section><?php endforeach;?>
<?php if($auth->hasRole('RULE_APPROVER')):?><section class="panel"><form method="post" action="rule_set_decision.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$id?>"><button class="btn primary" name="action" value="approve">Approve Rule Set</button><label>Rejection reason<textarea name="rejection_reason" minlength="3"></textarea></label><button class="btn secondary" name="action" value="reject">Reject</button></form></section><?php endif;?><?php require __DIR__.'/partials/footer.php';?>
